import struct
import wave

PAD, BOS, EOS = "_", "^", "$"

QUALITY_SAMPLE_RATES = {"x_low": 16000, "low": 16000,
                        "medium": 22050, "high": 22050}


def phonemes_to_ids(phonemes, phoneme_id_map):
    ids = list(phoneme_id_map[BOS])
    for phoneme in phonemes:
        if phoneme not in phoneme_id_map:
            continue
        ids.extend(phoneme_id_map[phoneme])
        ids.extend(phoneme_id_map[PAD])
    ids.extend(phoneme_id_map[EOS])
    return ids


def to_pcm16(samples):
    out = bytearray()
    for sample in samples:
        clipped = max(-1.0, min(1.0, sample))
        out += struct.pack("<h", int(clipped * 32767))
    return bytes(out)


def write_wav(fileobj, samples, sample_rate):
    with wave.open(fileobj, "wb") as writer:
        writer.setnchannels(1)
        writer.setsampwidth(2)
        writer.setframerate(sample_rate)
        writer.writeframes(to_pcm16(samples))


def voice_sample_rate(quality):
    if quality not in QUALITY_SAMPLE_RATES:
        raise ValueError(f"unknown quality tier {quality!r}")
    return QUALITY_SAMPLE_RATES[quality]


def parse_voice_name(name):
    locale, _, rest = name.partition("-")
    speaker, _, quality = rest.partition("-")
    language, _, region = locale.partition("_")
    if not (language and region and speaker and quality):
        raise ValueError(f"malformed voice name {name!r}")
    if quality not in QUALITY_SAMPLE_RATES:
        raise ValueError(f"unknown quality tier {quality!r}")
    return {"language": language, "region": region, "speaker": speaker,
            "quality": quality, "sample_rate": voice_sample_rate(quality)}


def scaled_duration(seconds, length_scale):
    return seconds * length_scale
